import { describe, it, expect, beforeEach } from 'vitest';
import {
  loadAuthProfiles,
  addProfile,
  removeProfile,
  listProfilesForProvider,
  isProfileInCooldown,
  getProfileStats,
  markProfileUsed,
  markProfileFailure,
  resetProfileCooldown,
  getNextAvailableProfile,
  orderProfilesByAvailability
} from '../../server/providers/auth-profiles.js';

function emptyStore() {
  return { version: 1, profiles: {}, order: {}, usageStats: {} };
}

describe('addProfile', () => {
  it('adds a profile with api_key credential', () => {
    const store = emptyStore();
    addProfile(store, 'anthropic:main', { key: 'sk-ant-test' });
    expect(store.profiles['anthropic:main']).toBeDefined();
    expect(store.profiles['anthropic:main'].key).toBe('sk-ant-test');
    expect(store.profiles['anthropic:main'].createdAt).toBeGreaterThan(0);
  });

  it('adds profile to provider order list', () => {
    const store = emptyStore();
    addProfile(store, 'openai:work', { key: 'sk-test' });
    expect(store.order.openai).toContain('openai:work');
  });

  it('does not duplicate in order list on re-add', () => {
    const store = emptyStore();
    addProfile(store, 'openai:work', { key: 'sk-1' });
    addProfile(store, 'openai:work', { key: 'sk-2' });
    expect(store.order.openai.filter(id => id === 'openai:work').length).toBe(1);
  });
});

describe('removeProfile', () => {
  it('removes a profile and its stats', () => {
    const store = emptyStore();
    addProfile(store, 'anthropic:test', { key: 'sk-test' });
    markProfileUsed(store, 'anthropic:test');
    removeProfile(store, 'anthropic:test');
    expect(store.profiles['anthropic:test']).toBeUndefined();
  });

  it('removes from order list', () => {
    const store = emptyStore();
    addProfile(store, 'openai:a', { key: '1' });
    addProfile(store, 'openai:b', { key: '2' });
    removeProfile(store, 'openai:a');
    expect(store.order.openai).not.toContain('openai:a');
    expect(store.order.openai).toContain('openai:b');
  });
});

describe('listProfilesForProvider', () => {
  it('returns profiles matching provider prefix', () => {
    const store = emptyStore();
    addProfile(store, 'openai:a', { key: '1' });
    addProfile(store, 'openai:b', { key: '2' });
    addProfile(store, 'anthropic:c', { key: '3' });
    const result = listProfilesForProvider(store, 'openai');
    expect(result).toHaveLength(2);
    expect(result).toContain('openai:a');
    expect(result).toContain('openai:b');
  });

  it('returns empty array for unknown provider', () => {
    const store = emptyStore();
    expect(listProfilesForProvider(store, 'unknown')).toHaveLength(0);
  });
});

describe('cooldown system', () => {
  it('profile is not in cooldown by default', () => {
    const store = emptyStore();
    addProfile(store, 'openai:main', { key: 'test' });
    expect(isProfileInCooldown(store, 'openai:main')).toBe(false);
  });

  it('marks profile in cooldown after failure', () => {
    const store = emptyStore();
    addProfile(store, 'openai:main', { key: 'test' });
    markProfileFailure(store, 'openai:main', 'rate_limit');
    expect(isProfileInCooldown(store, 'openai:main')).toBe(true);
  });

  it('resets cooldown', () => {
    const store = emptyStore();
    addProfile(store, 'openai:main', { key: 'test' });
    markProfileFailure(store, 'openai:main', 'rate_limit');
    resetProfileCooldown(store, 'openai:main');
    expect(isProfileInCooldown(store, 'openai:main')).toBe(false);
  });

  it('auth failure sets long cooldown', () => {
    const store = emptyStore();
    addProfile(store, 'openai:main', { key: 'test' });
    markProfileFailure(store, 'openai:main', 'auth');
    const stats = store.usageStats['openai:main'];
    expect(stats.cooldownUntil - stats.lastFailure).toBe(86400000);
  });
});

describe('getProfileStats', () => {
  it('returns null for nonexistent profile', () => {
    const store = emptyStore();
    expect(getProfileStats(store, 'noexist')).toBeNull();
  });

  it('returns stats for existing profile', () => {
    const store = emptyStore();
    addProfile(store, 'openai:work', { key: 'test' });
    markProfileUsed(store, 'openai:work');
    const stats = getProfileStats(store, 'openai:work');
    expect(stats.successCount).toBe(1);
    expect(stats.inCooldown).toBe(false);
  });
});

describe('getNextAvailableProfile', () => {
  it('returns null when no profiles exist', () => {
    const store = emptyStore();
    expect(getNextAvailableProfile(store, 'openai')).toBeNull();
  });

  it('returns available profile skipping cooled-down ones', () => {
    const store = emptyStore();
    addProfile(store, 'openai:a', { key: '1' });
    addProfile(store, 'openai:b', { key: '2' });
    markProfileFailure(store, 'openai:a', 'rate_limit');
    const next = getNextAvailableProfile(store, 'openai');
    expect(next).toBe('openai:b');
  });

  it('returns null when all profiles are in cooldown', () => {
    const store = emptyStore();
    addProfile(store, 'openai:a', { key: '1' });
    markProfileFailure(store, 'openai:a', 'auth');
    expect(getNextAvailableProfile(store, 'openai')).toBeNull();
  });
});

import { describe, it, expect } from 'vitest';
import { loadMcpServers } from '../../server/mcp-loader.js';
import { writeFileSync, unlinkSync } from 'fs';
import { join } from 'path';
import { tmpdir } from 'os';

function tmpFile(content) {
  const p = join(tmpdir(), `cmd-test-${Date.now()}-${Math.random().toString(36).slice(2)}.json`);
  writeFileSync(p, JSON.stringify(content, null, 2));
  return p;
}

describe('command injection prevention', () => {
  it('rejects shell metacharacters in args', () => {
    const metacharacters = [
      'arg;rm -rf /',
      'arg|cat /etc/passwd',
      'arg&background',
      'arg`whoami`',
      'arg$(id)',
      'arg(subshell)',
      'arg){close',
      'arg{open',
      'arg}close',
      'arg[bracket',
      'arg]bracket',
      'arg<redirect',
      'arg>redirect',
      'arg!history',
      'arg#comment',
      'arg~tilde',
    ];

    for (const arg of metacharacters) {
      const cfg = tmpFile({
        srv: { type: 'stdio', command: 'node', args: [arg] }
      });
      const result = loadMcpServers(cfg);
      expect(result).toEqual({});
      unlinkSync(cfg);
    }
  });

  it('rejects non-whitelisted commands', () => {
    const blocked = ['bash', 'sh', 'curl', 'wget', 'rm', 'cat', 'eval', 'exec'];
    for (const cmd of blocked) {
      const cfg = tmpFile({
        srv: { type: 'stdio', command: cmd, args: [] }
      });
      const result = loadMcpServers(cfg);
      expect(result).toEqual({});
      unlinkSync(cfg);
    }
  });

  it('accepts valid whitelisted commands with safe args', () => {
    const valid = [
      { command: 'node', args: ['server.js'] },
      { command: 'npx', args: ['@modelcontextprotocol/server'] },
      { command: 'python3', args: ['-m', 'mcp_server'] },
      { command: 'docker', args: ['run', 'mcp-image'] },
      { command: 'deno', args: ['run', 'server.ts'] },
      { command: 'bun', args: ['run', 'server.js'] },
    ];

    for (const { command, args } of valid) {
      const cfg = tmpFile({
        srv: { type: 'stdio', command, args }
      });
      const result = loadMcpServers(cfg);
      expect(result).toHaveProperty('srv');
      expect(result.srv.command).toBe(command);
      expect(result.srv.args).toEqual(args);
      unlinkSync(cfg);
    }
  });

  it('rejects path traversal in commands', () => {
    const cfg = tmpFile({
      srv: { type: 'stdio', command: '../../bin/sh', args: [] }
    });
    const result = loadMcpServers(cfg);
    expect(result).toEqual({});
    unlinkSync(cfg);
  });
});

import { describe, it, expect } from 'vitest';
import { readFileSync } from 'fs';
import { join, dirname } from 'path';
import { fileURLToPath } from 'url';

const __dirname = dirname(fileURLToPath(import.meta.url));

function readDesktopFile(relativePath) {
  return readFileSync(join(__dirname, '../../', relativePath), 'utf-8');
}

describe('XSS prevention', () => {
  it('DOMPurify is loaded in index.html', () => {
    const html = readDesktopFile('desktop/index.html');
    expect(html).toContain('dompurify');
    expect(html).toContain('purify.min.js');
  });

  it('all marked.parse calls are guarded by DOMPurify', () => {
    const markdownJs = readDesktopFile('desktop/modules/markdown.js');
    const sanitizedCalls = markdownJs.match(/DOMPurify\.sanitize\(marked\.parse\(/g) || [];
    expect(sanitizedCalls.length).toBeGreaterThan(0);

    const lines = markdownJs.split('\n');
    for (const line of lines) {
      if (line.includes('.innerHTML') && line.includes('marked.parse(')) {
        const hasSanitize = line.includes('DOMPurify.sanitize');
        const hasFallbackGuard = markdownJs.includes("typeof DOMPurify !== 'undefined'");
        expect(hasSanitize || hasFallbackGuard).toBe(true);
      }
    }
  });

  it('no direct innerHTML = marked.parse without DOMPurify guard', () => {
    const markdownJs = readDesktopFile('desktop/modules/markdown.js');
    const lines = markdownJs.split('\n');
    for (const line of lines) {
      if (line.includes('.innerHTML') && line.includes('marked.parse(')) {
        expect(line).toContain('DOMPurify');
      }
    }
  });

  it('CSP headers are set in main.js', () => {
    const mainJs = readDesktopFile('main.js');
    expect(mainJs).toContain('Content-Security-Policy');
    expect(mainJs).toContain("default-src 'self'");
    expect(mainJs).toContain('onHeadersReceived');
  });

  it('external URL validation exists in main.js', () => {
    const mainJs = readDesktopFile('main.js');
    expect(mainJs).toContain('isSafeExternalUrl');
    expect(mainJs).toContain("'https:'");
    expect(mainJs).toContain("'http:'");
    expect(mainJs).toContain("'mailto:'");
  });
});

import { describe, it, expect } from 'vitest';
import { loadMcpServers } from '../../server/mcp-loader.js';
import { writeFileSync, unlinkSync } from 'fs';
import { join } from 'path';
import { tmpdir } from 'os';

function tmpFile(rawContent) {
  const p = join(tmpdir(), `env-test-${Date.now()}-${Math.random().toString(36).slice(2)}.json`);
  writeFileSync(p, rawContent);
  return p;
}

describe('env var injection prevention', () => {
  it('allows ALLOWED_ENV_PREFIXES', () => {
    const prefixes = ['ANTHROPIC_', 'OPENAI_', 'GOOGLE_', 'GROQ_', 'DEEPSEEK_', 'MISTRAL_', 'XAI_', 'VENICE_', 'OPENROUTER_', 'OPENCLAWD_'];
    for (const prefix of prefixes) {
      const envKey = `${prefix}TEST_VAL`;
      process.env[envKey] = 'allowed-value';

      const cfg = tmpFile(JSON.stringify({
        srv: { type: 'http', url: `http://host:$\{${envKey}\}` }
      }));
      const result = loadMcpServers(cfg);
      expect(result.srv.url).toBe('http://host:allowed-value');

      delete process.env[envKey];
      unlinkSync(cfg);
    }
  });

  it('allows GITHUB_TOKEN', () => {
    process.env.GITHUB_TOKEN = 'ghp_test123';
    const cfg = tmpFile(JSON.stringify({
      srv: { type: 'http', url: 'http://host:${GITHUB_TOKEN}' }
    }));
    const result = loadMcpServers(cfg);
    expect(result.srv.url).toBe('http://host:ghp_test123');
    delete process.env.GITHUB_TOKEN;
    unlinkSync(cfg);
  });

  it('allows safe system var HOME', () => {
    const originalHome = process.env.HOME;
    process.env.HOME = '/home/testuser';

    const cfg = tmpFile(JSON.stringify({
      srv: { type: 'http', url: 'http://host:${HOME}' }
    }));
    const result = loadMcpServers(cfg);
    expect(result.srv.url).toBe('http://host:/home/testuser');

    process.env.HOME = originalHome;
    unlinkSync(cfg);
  });

  it('blocks BLOCKED_ENV_VARS', () => {
    const blocked = ['AWS_SECRET_ACCESS_KEY', 'AWS_SESSION_TOKEN', 'DATABASE_URL', 'PRIVATE_KEY', 'SSH_KEY', 'SUDO_ASKPASS'];
    for (const envKey of blocked) {
      process.env[envKey] = 'secret-value';

      const cfg = tmpFile(JSON.stringify({
        srv: { type: 'http', url: `http://host:$\{${envKey}\}` }
      }));
      const result = loadMcpServers(cfg);
      expect(result.srv.url).toBe('http://host:');

      delete process.env[envKey];
      unlinkSync(cfg);
    }
  });

  it('blocks vars without allowed prefix', () => {
    process.env.MY_CUSTOM_SECRET = 'secret';
    const cfg = tmpFile(JSON.stringify({
      srv: { type: 'http', url: 'http://host:${MY_CUSTOM_SECRET}' }
    }));
    const result = loadMcpServers(cfg);
    expect(result.srv.url).toBe('http://host:');
    delete process.env.MY_CUSTOM_SECRET;
    unlinkSync(cfg);
  });
});

import { describe, it, expect } from 'vitest';
import path from 'path';
import { Workspace, createWorkspace } from '../../server/workspace.js';

describe('Workspace restriction', () => {
  const root = '/tmp/test-workspace';

  it('creates workspace with root path', () => {
    const ws = new Workspace(root);
    expect(ws.root).toBe(path.resolve(root));
  });

  it('throws without root path', () => {
    expect(() => new Workspace()).toThrow('Workspace root path is required');
  });

  it('resolves valid paths within workspace', () => {
    const ws = new Workspace(root);
    const resolved = ws.resolve('file.txt');
    expect(resolved).toBe(path.join(root, 'file.txt'));
  });

  it('resolves nested paths', () => {
    const ws = new Workspace(root);
    const resolved = ws.resolve('subdir/file.txt');
    expect(resolved).toBe(path.join(root, 'subdir/file.txt'));
  });

  it('blocks path traversal with ..', () => {
    const ws = new Workspace(root);
    expect(() => ws.resolve('../etc/passwd')).toThrow('blocked pattern');
  });

  it('blocks null bytes', () => {
    const ws = new Workspace(root);
    expect(() => ws.resolve('file\0.txt')).toThrow('blocked pattern');
  });

  it('blocks paths escaping workspace via absolute path', () => {
    const ws = new Workspace(root);
    expect(() => ws.resolve('/etc/passwd')).toThrow('escapes workspace');
  });

  it('blocks dotfiles by default', () => {
    const ws = new Workspace(root);
    expect(() => ws.resolve('.env')).toThrow('Dotfile access not allowed');
  });

  it('allows dotfiles when configured', () => {
    const ws = new Workspace(root, { allowDotfiles: true });
    const resolved = ws.resolve('.config');
    expect(resolved).toBe(path.join(root, '.config'));
  });

  it('blocks sensitive paths', () => {
    const ws = new Workspace(root, { allowDotfiles: true });
    expect(() => ws.resolve('.git/config')).toThrow("Access to '.git' is restricted");
  });

  it('blocks node_modules access', () => {
    const ws = new Workspace(root);
    expect(() => ws.resolve('node_modules/pkg/index.js')).toThrow("Access to 'node_modules' is restricted");
  });

  it('enforces allowed extensions', () => {
    const ws = new Workspace(root, { allowedExtensions: ['.txt', '.md'] });
    expect(() => ws.resolve('script.sh')).toThrow("File extension '.sh' not allowed");
  });

  it('allows matching extensions', () => {
    const ws = new Workspace(root, { allowedExtensions: ['.txt', '.md'] });
    const resolved = ws.resolve('readme.md');
    expect(resolved).toBe(path.join(root, 'readme.md'));
  });

  it('validate returns valid result for good paths', () => {
    const ws = new Workspace(root);
    const result = ws.validate('file.txt');
    expect(result.valid).toBe(true);
    expect(result.resolved).toBe(path.join(root, 'file.txt'));
  });

  it('validate returns error for bad paths', () => {
    const ws = new Workspace(root);
    const result = ws.validate('../etc/passwd');
    expect(result.valid).toBe(false);
    expect(result.error).toContain('blocked pattern');
  });

  it('relativePath computes relative from absolute', () => {
    const ws = new Workspace(root);
    const rel = ws.relativePath(path.join(root, 'subdir/file.txt'));
    expect(rel).toBe(path.join('subdir', 'file.txt'));
  });

  it('relativePath throws for outside paths', () => {
    const ws = new Workspace(root);
    expect(() => ws.relativePath('/etc/passwd')).toThrow('outside workspace');
  });

  it('createWorkspace helper works', () => {
    const ws = createWorkspace(root);
    expect(ws).toBeInstanceOf(Workspace);
    expect(ws.root).toBe(path.resolve(root));
  });

  it('blocks custom blocked paths', () => {
    const ws = new Workspace(root, { blockedPaths: ['secret-dir'] });
    expect(() => ws.resolve('secret-dir/data.json')).toThrow("Access to 'secret-dir' is restricted");
  });

  it('requires file path argument', () => {
    const ws = new Workspace(root);
    expect(() => ws.resolve()).toThrow('File path is required');
  });
});

import { describe, it, expect, beforeEach } from 'vitest';
import { TaskManager } from '../../server/agents/task-manager.js';
import { TASK_STATUS } from '../../server/agents/types.js';

describe('TaskManager', () => {
  let tm;

  beforeEach(() => {
    tm = new TaskManager();
  });

  it('creates a task', () => {
    const task = tm.createTask({ title: 'Fix bug' });
    expect(task.id).toBe('1');
    expect(task.title).toBe('Fix bug');
    expect(task.status).toBe(TASK_STATUS.pending);
    expect(task.owner).toBeNull();
  });

  it('requires a title', () => {
    expect(() => tm.createTask({})).toThrow('Task title is required');
  });

  it('auto-increments IDs', () => {
    const t1 = tm.createTask({ title: 'A' });
    const t2 = tm.createTask({ title: 'B' });
    expect(t1.id).toBe('1');
    expect(t2.id).toBe('2');
  });

  it('gets a task by ID', () => {
    tm.createTask({ title: 'Find me' });
    expect(tm.getTask('1').title).toBe('Find me');
    expect(tm.getTask('99')).toBeNull();
  });

  it('lists all tasks', () => {
    tm.createTask({ title: 'A' });
    tm.createTask({ title: 'B' });
    expect(tm.listTasks()).toHaveLength(2);
  });

  it('updates a task', () => {
    tm.createTask({ title: 'Old' });
    const updated = tm.updateTask('1', { title: 'New', status: TASK_STATUS.completed });
    expect(updated.title).toBe('New');
    expect(updated.status).toBe(TASK_STATUS.completed);
  });

  it('throws when updating non-existent task', () => {
    expect(() => tm.updateTask('99', { title: 'X' })).toThrow("Task '99' not found");
  });

  it('rejects invalid status values', () => {
    tm.createTask({ title: 'Test' });
    expect(() => tm.updateTask('1', { status: 'bogus' })).toThrow("Invalid status: 'bogus'");
  });

  it('deletes a task and cleans up references', () => {
    const t1 = tm.createTask({ title: 'Blocker' });
    const t2 = tm.createTask({ title: 'Blocked' });
    tm.updateTask(t2.id, { blockedBy: [t1.id] });
    tm.updateTask(t1.id, { blocks: [t2.id] });

    tm.deleteTask(t1.id);
    expect(tm.getTask(t1.id)).toBeNull();
    expect(tm.getTask(t2.id).blockedBy).toEqual([]);
  });

  it('assigns a task to an agent', () => {
    tm.createTask({ title: 'Work' });
    const task = tm.assignTask('1', 'agent-1');
    expect(task.owner).toBe('agent-1');
    expect(task.status).toBe(TASK_STATUS.in_progress);
  });

  it('getAvailableTasks() returns unblocked pending tasks', () => {
    const t1 = tm.createTask({ title: 'Blocker' });
    const t2 = tm.createTask({ title: 'Blocked' });
    tm.updateTask(t2.id, { blockedBy: [t1.id] });
    const t3 = tm.createTask({ title: 'Free' });

    const available = tm.getAvailableTasks();
    expect(available.map(t => t.id)).toContain(t1.id);
    expect(available.map(t => t.id)).toContain(t3.id);
    expect(available.map(t => t.id)).not.toContain(t2.id);
  });

  it('getBlockedTasks() returns tasks with incomplete blockers', () => {
    const t1 = tm.createTask({ title: 'Blocker' });
    const t2 = tm.createTask({ title: 'Blocked' });
    tm.updateTask(t2.id, { blockedBy: [t1.id] });

    expect(tm.getBlockedTasks().map(t => t.id)).toContain(t2.id);

    tm.updateTask(t1.id, { status: TASK_STATUS.completed });
    expect(tm.getBlockedTasks()).toHaveLength(0);
  });
});

import { describe, it, expect, vi, beforeEach } from 'vitest';
import { AgentManager } from '../../server/agents/agent-manager.js';

vi.mock('../../server/providers/index.js', () => ({
  getProvider: vi.fn(() => ({
    query: vi.fn(async function* ({ prompt }) {
      yield { type: 'text', content: 'mock response' };
    }),
    abort: vi.fn(() => true)
  }))
}));

describe('AgentManager', () => {
  let manager;

  beforeEach(() => {
    manager = new AgentManager();
  });

  it('creates an agent', () => {
    const agent = manager.createAgent({ name: 'agent1' });
    expect(agent.name).toBe('agent1');
  });

  it('rejects duplicate agent names', () => {
    manager.createAgent({ name: 'dup' });
    expect(() => manager.createAgent({ name: 'dup' })).toThrow("Agent 'dup' already exists");
  });

  it('gets an agent by name', () => {
    manager.createAgent({ name: 'find-me' });
    expect(manager.getAgent('find-me')).not.toBeNull();
    expect(manager.getAgent('missing')).toBeNull();
  });

  it('lists all agents', () => {
    manager.createAgent({ name: 'a1' });
    manager.createAgent({ name: 'a2' });
    const list = manager.listAgents();
    expect(list).toHaveLength(2);
    expect(list.map(a => a.name)).toContain('a1');
  });

  it('kills an agent', () => {
    manager.createAgent({ name: 'doomed' });
    expect(manager.killAgent('doomed')).toBe(true);
    expect(manager.getAgent('doomed')).toBeNull();
  });

  it('throws when killing non-existent agent', () => {
    expect(() => manager.killAgent('ghost')).toThrow("Agent 'ghost' not found");
  });

  it('kills all agents', () => {
    manager.createAgent({ name: 'x1' });
    manager.createAgent({ name: 'x2' });
    const count = manager.killAll();
    expect(count).toBe(2);
    expect(manager.listAgents()).toHaveLength(0);
  });

  it('ask() creates ephemeral agent and returns response', async () => {
    const response = await manager.ask('test message');
    expect(response).toBe('mock response');
    expect(manager.listAgents()).toHaveLength(0);
  });

  it('sendMessage() delivers to target agent', () => {
    manager.createAgent({ name: 'sender' });
    manager.createAgent({ name: 'receiver' });
    manager.sendMessage('sender', 'receiver', 'hello');
    const receiver = manager.getAgent('receiver');
    expect(receiver.inbox).toHaveLength(1);
    expect(receiver.inbox[0].content).toBe('hello');
  });

  it('sendMessage() throws for missing target', () => {
    manager.createAgent({ name: 'sender' });
    expect(() => manager.sendMessage('sender', 'nobody', 'hi')).toThrow("Agent 'nobody' not found");
  });

  it('broadcast() sends to all except sender', () => {
    manager.createAgent({ name: 'broadcaster' });
    manager.createAgent({ name: 'listener1' });
    manager.createAgent({ name: 'listener2' });
    const count = manager.broadcast('broadcaster', 'announcement');
    expect(count).toBe(2);
    expect(manager.getAgent('listener1').inbox).toHaveLength(1);
    expect(manager.getAgent('broadcaster').inbox).toHaveLength(0);
  });

  it('emits agent:created event', () => {
    const handler = vi.fn();
    manager.on('agent:created', handler);
    manager.createAgent({ name: 'evt' });
    expect(handler).toHaveBeenCalledWith(expect.objectContaining({ name: 'evt' }));
  });
});

import { describe, it, expect, vi, beforeEach } from 'vitest';
